from(bucket: "ems")
  |> range(start: -1h)
  |> filter(fn: (r) => r._measurement == "medidor" and r.escenario == "live" and r._field == "p_total_kw")
  // Última muestra: el valor cambia en cuanto el gemelo aplica un evento
  |> last()
  |> keep(columns: ["_value"])

