import "date"
import "timezone"

option location = timezone.location(name: "America/Panama")

from(bucket: "ems")
  |> range(start: date.truncate(t: now(), unit: 1d))
  |> filter(fn: (r) => r._measurement == "medidor" and r.escenario == "live")
  |> filter(fn: (r) => r._field == "p_total_kw" or r._field == "p_red_kw" or r._field == "precio_usd_kwh")
  // Mediana de 15 min (3 muestras de 5 min): quita el pico aislado de ~120 kW que deja cada
  // reinicio del simulador sin recortar picos reales (pico físico de 28 días: 137,9 kW tras el filtro)
  |> aggregateWindow(every: 15m, fn: median, createEmpty: false)
  |> pivot(rowKey: ["_time"], columnKey: ["_field"], valueColumn: "_value")
  |> map(fn: (r) => {
      red = if exists r.p_red_kw then r.p_red_kw else r.p_total_kw
      return {r with _value: if red > 0.0 then red * r.precio_usd_kwh else 0.0}
  })
  |> integral(unit: 1h)
  |> map(fn: (r) => ({_time: now(), _value: r._value, _field: "Compra a la red"}))
  |> group(columns: ["_field"])

import "date"
import "timezone"

option location = timezone.location(name: "America/Panama")

from(bucket: "ems")
  |> range(start: date.truncate(t: now(), unit: 1d))
  |> filter(fn: (r) => r._measurement == "medidor" and r.escenario == "live")
  |> filter(fn: (r) => r._field == "p_total_kw" or r._field == "p_red_kw" or r._field == "precio_usd_kwh")
  // Mediana de 15 min (3 muestras de 5 min): quita el pico aislado de ~120 kW que deja cada
  // reinicio del simulador sin recortar picos reales (pico físico de 28 días: 137,9 kW tras el filtro)
  |> aggregateWindow(every: 15m, fn: median, createEmpty: false)
  |> pivot(rowKey: ["_time"], columnKey: ["_field"], valueColumn: "_value")
  |> map(fn: (r) => {
      red = if exists r.p_red_kw then r.p_red_kw else r.p_total_kw
      return {r with _value: if red < 0.0 then -red * 0.1 else 0.0}
  })
  |> integral(unit: 1h)
  |> map(fn: (r) => ({_time: now(), _value: r._value, _field: "Crédito solar"}))
  |> group(columns: ["_field"])

from(bucket: "ems")
  |> range(start: -1h)
  |> filter(fn: (r) => r._measurement == "medidor" and r.escenario == "live")
  |> filter(fn: (r) => r._field == "p_hvac_kw" or r._field == "p_luces_kw" or r._field == "p_equipos_kw" or r._field == "p_fija_kw")
  // Última muestra: el valor cambia en cuanto el gemelo aplica un evento
  |> last()
  |> group()
  |> map(fn: (r) => ({uso: if r._field == "p_hvac_kw" then "Climatización" else if r._field == "p_luces_kw" then "Iluminación"
      else if r._field == "p_equipos_kw" then "Equipos y enchufes" else "Cargas fijas", _value: r._value}))
  |> sort(columns: ["_value"], desc: true)

from(bucket: "ems")
  |> range(start: -1h)
  |> filter(fn: (r) => r._measurement == "medidor" and r.escenario == "live" and r._field == "p_red_kw")
  // Última muestra: el valor cambia en cuanto el gemelo aplica un evento
  |> last()
  |> keep(columns: ["_value"])

from(bucket: "ems")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "medidor" and r.escenario == "live")
  |> filter(fn: (r) => r._field == "p_total_kw")
  // Mediana de 15 min (3 muestras de 5 min): quita el pico aislado de ~120 kW que deja cada
  // reinicio del simulador sin recortar picos reales (pico físico de 28 días: 137,9 kW tras el filtro)
  |> aggregateWindow(every: if int(v: v.windowPeriod) > int(v: 15m) then v.windowPeriod else 15m, fn: median, createEmpty: false)
  |> set(key: "_field", value: "demanda_15min_kw")
  |> keep(columns: ["_time", "_value", "_field"])
